        transaction.xid,
        sql_literal(&format_lsn(transaction.begin_lsn)),
        sql_literal(&format_lsn(transaction.commit_lsn)),
        sql_literal(&format_lsn(transaction.end_lsn)),
        transaction.commit_time_micros,
